  ('museo-asur', 'Museo de Arte Indígena (ASUR)', 'Textil & Indígena', 'Pasaje Iturricha Nº 314 (La Recoleta)', 'Exhibición de arte textil tradicional de las culturas Jalq''a y Tarabuco, mostrando cosmovisiones andinas con telares vivos y bordados ancestrales.', 'Lun - Sáb: 08:30 - 18:00', -19.0535, -65.2534, 120, 'Rara'::public.rarity, 'palette', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDUA6whty5OmehKlWp2Tw95O6ncPDGdhnNJSP87-KfXOvdjxl6D5YTBBrpBCet048n5c4Z5_Vbo4GrvKXoxleq2wiqGdKthALv0XWtxwl9vRciffuzm7V_6ibwyFOorI3SqFEKRA0JsbeSHaPCXFrZ2TSlIOepNp0SsjnQ2Wi3KsTujQ5ITECdRwyNjGCY0ROuvRhom_r5chTjopGPd8HZbEA78US4U0BWtnoAMR4g', 'museo', 29, 75),
  ('musef', 'Museo Nacional de Etnografía y Folklore (MUSEF)', 'Etnográfico', 'Calle España Nº 74', 'Instalado en una señorial casona virreinal, custodia máscaras ceremoniales bolivianas, plumería sagrada, cerámica precolombina y numismática.', 'Mar - Sáb: 09:00 - 17:00', -19.0488, -65.2605, 120, 'Rara'::public.rarity, 'diversity_3', 'https://lh3.googleusercontent.com/aida-public/AB6AXuA8muneXTSFIpSCVXoZKiuwDAYtpITENkStBmwdYeakpacSt8YXbOJ21B2_mhZ52jOKOZXWm0d9SCnKpaKh1ht-pTz34EztkHhmm3uEzddjFveLzpk9qXSZ_LxUlTuQtQuSdssavih3pTGX-g5yhY_LfwCHW9WBEYqThKUZ3onMElACKlaPggFitNTlDUxqrA2VcJyiix2fky0bLLfLnwSUMV5nDRCUYLB2J_LdPSk', 'museo', 52, 38),
  ('museo-gutierrez-valenzuela', 'Museo Universitario Dr. Alfredo Gutiérrez Valenzuela', 'Bellas Artes', 'Plaza 25 de Mayo esq. Calvo', 'Colección señorial de porcelanas de Sèvres, cristal de Baccarat, muebles virreinales de madera taraceada y lienzos de maestros europeos y coloniales.', 'Lun - Vie: 08:30 - 16:30', -19.0475, -65.2589, 100, 'Común'::public.rarity, 'history_edu', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBFuzzo0uHbqHKIFqThvfbhLs8fwKBrpjpr8b9epNwT0-5xkQ7_rrWkGHQXOPEcgVPEhlnfxZK_biCUEz4g0KWm9XjgzXZkdG6XBRVdr8ObiO-jq3AmHH7P39pHSkwRsqPVqTzw-EMh8UwRZM_AZhdlmVeh6jd-OA74RHM61dLMT4O9YjVqjL7-HxUHcSgoVuRWu4FKD7qIUeXwpaxt6mfYyZH_CU8-KUuoXCvTc9U', 'museo', 44, 54),
  ('museo-catedral', 'Museo de la Catedral', 'Arte Sacro', 'Calle Nicolás Ortiz Nº 61', 'Tesoros litúrgicos más ricos de América del Sur. Custodia la imagen enjoyada de la Virgen de Guadalupe, orfebrería de plata potosina y custodias coloniales.', 'Lun - Vie: 10:00 - 17:00', -19.0483, -65.2601, 130, 'Épica'::public.rarity, 'church', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDj0qwOSE1Va28E5Hrx2kNZA9hr3TP1NkdaWrxEg8MjiOehQYd2EzPL2xin5pZMUVUFnQQNeKLE0beZC1Dwe7Qbb6yAkSW1iAwY_IUXT0aXhO1Rdi_UGqSQYRqlO6OdfSzJXw2EDJf020n7E9Zl1J_6ogBp62osOXeAJRAvLay4dSvXteE_9X-SAQ44NJ6YEbOBHfgsk6AYoh6_zk3NzfJbntM-v9-6oEf0-fVqHus', 'museo', 50, 43),
  ('museo-la-recoleta', 'Museo Franciscano de La Recoleta', 'Conventual', 'Plaza Pedro de Anzúrez s/n', 'Convento franciscano de 1601 con claustros de naranjos centenarios, sillería tallada en cedro y una terraza panorámica con mirador a la ciudad.', 'Lun - Sáb: 09:00 - 16:30', -19.0531, -65.2528, 120, 'Rara'::public.rarity, 'landscape', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDUA6whty5OmehKlWp2Tw95O6ncPDGdhnNJSP87-KfXOvdjxl6D5YTBBrpBCet048n5c4Z5_Vbo4GrvKXoxleq2wiqGdKthALv0XWtxwl9vRciffuzm7V_6ibwyFOorI3SqFEKRA0JsbeSHaPCXFrZ2TSlIOepNp0SsjnQ2Wi3KsTujQ5ITECdRwyNjGCY0ROuvRhom_r5chTjopGPd8HZbEA78US4U0BWtnoAMR4g', 'museo', 24, 79),
  ('convento-santa-clara', 'Museo del Convento de Santa Clara', 'Arte Sacro', 'Calle Calvo Nº 212', 'Fundado en 1639 por las monjas clarisas. Exhibe pintura barroca mestiza de Bernardo Bitti y Melchor Pérez de Holguín, instrumentos de coro y criptas.', 'Lun - Vie: 09:00 - 12:30, 15:00 - 17:30', -19.0498, -65.2575, 110, 'Rara'::public.rarity, 'auto_stories', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAvDj7w00yuM6MrDp97o1RJk3Mev-xafLPRrBCsbvd-r6RRGJ3LlEG0mckzysZghIWg3EQebTfv5nIrp54Z4gfs-_VMW_1RIR1UhbztwnC7roeNcqiE4Com0yqP3WeopfUDPfohexYXOF3p6E569UbYjI0o-u3gLnnTwvx-pUT0aD1EL55Obw5jtJCuidQDmFUUb1CUtGZiIhVNfW2-rZNBfvhibVENreAlNlDyIFA', 'museo', 58, 62),
  ('parque-cretacico', 'Parque Cretácico (Cal Orck''O)', 'Paleontología', 'Carretera a Cochabamba Km 5', 'El farallón con más de 12.000 huellas de dinosaurios más grande del mundo. Incluye réplicas a escala real de titanosaurios y carnotauros.', 'Mar - Dom: 09:00 - 17:00', -19.0062, -65.2344, 150, 'Épica'::public.rarity, 'pets', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCjpFCmwe14ldYgNVQEWbeqE4JhpZX2HGQf8EI8SWZWCyr3Tat0F1V8RCmzvrPnyh7f-ZoJKxEYK-HR91iPYW2AciHQspz6AtQsqgdzrU9WruH_UhKqRvPBfwTMy1fNJFYBiuxkC7PL_EHV-J7i1xzvt5iiFtum8bm_G-JCwnOlDrCDoSFhvYiLAIpY_8G_LV8DJHJxRF44x4bp_MZlPMgkxs7GYAFwCn4gEXACwKc', 'museo', 16, 20),
  ('museo-casa-del-tesoro', 'Museo Casa del Tesoro', 'Histórico & Numismática', 'Calle San Alberto Nº 156', 'Antiguo tesoro real y casona virreinal que conserva lingotes, monedas de plata macuquinas de la Real Casa de Moneda y relicarios coloniales.', 'Lun - Vie: 09:00 - 16:00', -19.0465, -65.2612, 100, 'Común'::public.rarity, 'savings', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAhPaU2WUwsQ4lk5xEhglxgPqdGA3RKFf5foN06xZyXDiQLV0ILgsseml0ZDAc9rbwjQKhu5bWmdZazseSJwdvQNVbxuIAkJNTci0hXx-N4oDHdkbO42yx1mRaFjO9G9VQ5UK8OvNFQOt6HsORRdonvcKH0ubYf8_Hqr4Ro1TndeMInfEt6WG-QS5xIQLxrGe-zrs7l8dVzojBA160ej5qqRa5hxbCt8uduZXI2Afo', 'museo', 31, 34),
  ('museo-del-pan', 'Museo del Pan', 'Tradición Culinaria', 'Calle San Alberto Nº 245', 'Homenaje a los legendarios hornos de leña coloniales y a las maestras panificadoras de Sucre, con la historia del pan de batalla, tantawawas y empanadas.', 'Mar - Sáb: 09:00 - 18:00', -19.046, -65.262, 100, 'Común'::public.rarity, 'bakery_dining', 'https://lh3.googleusercontent.com/aida-public/AB6AXuA8muneXTSFIpSCVXoZKiuwDAYtpITENkStBmwdYeakpacSt8YXbOJ21B2_mhZ52jOKOZXWm0d9SCnKpaKh1ht-pTz34EztkHhmm3uEzddjFveLzpk9qXSZ_LxUlTuQtQuSdssavih3pTGX-g5yhY_LfwCHW9WBEYqThKUZ3onMElACKlaPggFitNTlDUxqrA2VcJyiix2fky0bLLfLnwSUMV5nDRCUYLB2J_LdPSk', 'museo', 27, 30),
  ('museo-del-chocolate', 'Museo del Chocolate', 'Gastronomía', 'Calle Calvo Nº 284', 'La tradición chocolatera de Sucre. Un recorrido interactivo desde la semilla de cacao silvestre amazónico hasta las famosas fábricas y bombones chuquisaqueños.', 'Lun - Dom: 09:30 - 20:00', -19.049, -65.2585, 100, 'Común'::public.rarity, 'cookie', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBFjsbvQizkh8eD2wbNOYYZc7u-GAhxK78XrLwC7jWoEQ0q8lwqsN3vyB0Gi4gpWarL5SILPDF0QsDt23JEs33vaTqvh9-kR1A61_j-gtnt7pEZ4DT-lqYrqOwycB38Dnox63BNRG-zUFvVtiDbzr8elhLTRoy7kIztJQgoXerPxM3MI2BLJ6KUufw5J1p6TFyGaFJlM1Hq59Jc-vkcBm5D5XX5sHhfZnl_Eaq7HTk', 'museo', 64, 56),
  ('san-felipe-neri', 'San Felipe Neri', 'Patrimonio', 'Terrazas Coloniales y Cúpulas', 'Azotea embaldosada con tejas de barro cocido y barandales que brindan una perspectiva única de los campanarios barrocos de la ciudad blanca.', null, -19.0495, -65.2608, 100, 'Común'::public.rarity, 'roofing', 'https://lh3.googleusercontent.com/aida-public/AB6AXuA8muneXTSFIpSCVXoZKiuwDAYtpITENkStBmwdYeakpacSt8YXbOJ21B2_mhZ52jOKOZXWm0d9SCnKpaKh1ht-pTz34EztkHhmm3uEzddjFveLzpk9qXSZ_LxUlTuQtQuSdssavih3pTGX-g5yhY_LfwCHW9WBEYqThKUZ3onMElACKlaPggFitNTlDUxqrA2VcJyiix2fky0bLLfLnwSUMV5nDRCUYLB2J_LdPSk', 'parada', 62, 22),
  ('catedral-metropolitana', 'Catedral Metropolitana', 'Patrimonio', 'Torre y Mirador del Campanario', 'Campanario histórico que domina la Plaza 25 de Mayo, con relojes antiguos y una vista imponente del damero central colonial.', null, -19.0483, -65.2601, 100, 'Común'::public.rarity, 'church', null, 'parada', null, null),
  ('la-recoleta', 'La Recoleta', 'Patrimonio', 'Mirador Franciscano de la Colina', 'Ubicado a las faldas del cerro Churuquella; su mirador histórico enmarca la geografía completa de la capital andina.', null, -19.0531, -65.2528, 100, 'Común'::public.rarity, 'landscape', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDUA6whty5OmehKlWp2Tw95O6ncPDGdhnNJSP87-KfXOvdjxl6D5YTBBrpBCet048n5c4Z5_Vbo4GrvKXoxleq2wiqGdKthALv0XWtxwl9vRciffuzm7V_6ibwyFOorI3SqFEKRA0JsbeSHaPCXFrZ2TSlIOepNp0SsjnQ2Wi3KsTujQ5ITECdRwyNjGCY0ROuvRhom_r5chTjopGPd8HZbEA78US4U0BWtnoAMR4g', 'parada', 25, 78),
  ('mirador-santa-teresa', 'Mirador Santa Teresa', 'Patrimonio', 'Torreón y Balcones de Clausura', 'Mirador elevado del antiguo convento carmelita de clausura con vistas privilegiadas hacia los cerros tutelares Sica Sica y Churuquella.', null, -19.0485, -65.256, 100, 'Común'::public.rarity, 'visibility', null, 'parada', null, null),
  ('residencia-severo-fernandez', 'Residencia Severo Fernández de Alonso', 'Patrimonio', 'Mansión del 22° Presidente de Bolivia', 'Imponente arquitectura señorial de finales del siglo XIX perteneciente al mandatario que gobernó durante la convulsa Guerra Federal.', null, -19.0492, -65.2615, 100, 'Común'::public.rarity, 'villa', null, 'parada', null, null),
