  ('museo-costumbrista', 'Museo Costumbrista', 'Patrimonio', 'Tradiciones y Vida Criolla Colonial', 'Colección viva de atuendos de época, instrumentos de salón, bargueños coloniales y representaciones de la vida aristocrática chuquisaqueña.', null, -19.047, -65.258, 100, 'Común'::public.rarity, 'history', null, 'parada', null, null),
