insert into public.route_stops (route_id, site_id, position, subtitle, detail) values
  ('ruta-panoramica', 'san-felipe-neri', 1, 'Terrazas Coloniales y Cúpulas', 'Azotea embaldosada con tejas de barro cocido y barandales que brindan una perspectiva única de los campanarios barrocos de la ciudad blanca.'),
  ('ruta-panoramica', 'catedral-metropolitana', 2, 'Torre y Mirador del Campanario', 'Campanario histórico que domina la Plaza 25 de Mayo, con relojes antiguos y una vista imponente del damero central colonial.'),
  ('ruta-panoramica', 'la-recoleta', 3, 'Mirador Franciscano de la Colina', 'Ubicado a las faldas del cerro Churuquella; su mirador histórico enmarca la geografía completa de la capital andina.'),
  ('ruta-panoramica', 'mirador-santa-teresa', 4, 'Torreón y Balcones de Clausura', 'Mirador elevado del antiguo convento carmelita de clausura con vistas privilegiadas hacia los cerros tutelares Sica Sica y Churuquella.'),
  ('ruta-presidencial', 'residencia-severo-fernandez', 1, 'Mansión del 22° Presidente de Bolivia', 'Imponente arquitectura señorial de finales del siglo XIX perteneciente al mandatario que gobernó durante la convulsa Guerra Federal.'),
  ('ruta-presidencial', 'residencia-jose-gutierrez', 2, 'El Último Presidente Liberal', 'Residencia histórica del presidente economista José Gutiérrez Guerra (''El Último Oligarca''), testigo de la bonanza del estaño.'),
  ('ruta-presidencial', 'palacete-la-florida', 3, 'Residencia Campestre de Aniceto Arce', 'Lujosa villa y jardines versallescos construidos por el presidente Aniceto Arce, pionero de los ferrocarriles en Bolivia.'),
  ('ruta-presidencial', 'casa-de-la-libertad', 4, 'Galería y Salón de los Presidentes', 'Salón dedicado con los cuadros al óleo oficiales de los mandatarios bolivianos junto a la espada victoriosa de Sucre y la Constitución original.'),
  ('ruta-presidencial', 'cementerio-general', 5, 'Mausoleos y Tumbas Presidenciales', 'Mausoleos de mármol de Carrara donde descansan los restos de presidentes de la nación, próceres de la independencia y poetas insignes.'),
  ('ruta-colonial', 'casa-de-la-libertad', 1, 'Claustro Colonial Jesuita de 1621', 'Antigua Universidad Pontificia San Francisco Xavier y cuna de la independencia americana. Corazón indiscutible de Sucre.'),
  ('ruta-colonial', 'musef', 2, 'Casona Colonial Calle España', 'Patio interior con arquería de medio punto, aljibe de piedra y techumbres de madera tallada que custodian milenarias expresiones culturales.'),
  ('ruta-colonial', 'museo-costumbrista', 3, 'Tradiciones y Vida Criolla Colonial', 'Colección viva de atuendos de época, instrumentos de salón, bargueños coloniales y representaciones de la vida aristocrática chuquisaqueña.'),
  ('ruta-colonial', 'palacete-guereo', 4, 'Mansión Señorial de Transición Colonial', 'Palacete señorial de amplias terrazas y arcos coloniales, rodeado de frondosos jardines botánicos andinos.');
insert into public.cards (id, site_id, title, category, category_label, rarity, hint, hint_icon, short_history, image_url) values
  ('casa-de-la-libertad', 'casa-de-la-libertad', 'Casa de la Libertad', 'colonial', 'Colonial', 'Épica'::public.rarity, 'Plaza 25 de Mayo · Salón de la Independencia', 'verified', 'El templo cívico más sagrado de Bolivia. En su imponente Salón Virreinal resonaron las voces que declararon la libertad americana y alberga la histórica galería presidencial.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAvDj7w00yuM6MrDp97o1RJk3Mev-xafLPRrBCsbvd-r6RRGJ3LlEG0mckzysZghIWg3EQebTfv5nIrp54Z4gfs-_VMW_1RIR1UhbztwnC7roeNcqiE4Com0yqP3WeopfUDPfohexYXOF3p6E569UbYjI0o-u3gLnnTwvx-pUT0aD1EL55Obw5jtJCuidQDmFUUb1CUtGZiIhVNfW2-rZNBfvhibVENreAlNlDyIFA'),
  ('cementerio-general', 'cementerio-general', 'Cementerio General', 'mistica', 'Presidencial', 'Épica'::public.rarity, 'Visita los mausoleos presidenciales', 'location_on', 'Custodio de presidentes, príncipes y poetas. Sus senderos arbolados guardan los secretos más profundos y los sepulcros de líderes de la República.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAhPaU2WUwsQ4lk5xEhglxgPqdGA3RKFf5foN06xZyXDiQLV0ILgsseml0ZDAc9rbwjQKhu5bWmdZazseSJwdvQNVbxuIAkJNTci0hXx-N4oDHdkbO42yx1mRaFjO9G9VQ5UK8OvNFQOt6HsORRdonvcKH0ubYf8_Hqr4Ro1TndeMInfEt6WG-QS5xIQLxrGe-zrs7l8dVzojBA160ej5qqRa5hxbCt8uduZXI2Afo'),
  ('la-recoleta', 'la-recoleta', 'La Recoleta', 'colonial', 'Panorámica', 'Rara'::public.rarity, 'Escanear en plaza del mirador', 'qr_code', 'Construido en el sitio exacto donde se fundó la Villa de La Plata en 1538. Su mirador regala un atardecer colonial inigualable.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDUA6whty5OmehKlWp2Tw95O6ncPDGdhnNJSP87-KfXOvdjxl6D5YTBBrpBCet048n5c4Z5_Vbo4GrvKXoxleq2wiqGdKthALv0XWtxwl9vRciffuzm7V_6ibwyFOorI3SqFEKRA0JsbeSHaPCXFrZ2TSlIOepNp0SsjnQ2Wi3KsTujQ5ITECdRwyNjGCY0ROuvRhom_r5chTjopGPd8HZbEA78US4U0BWtnoAMR4g'),
  ('castillo-de-la-glorieta', 'castillo-de-la-glorieta', 'Castillo Glorieta', 'presidencial', 'Arquitectónico', 'Legendaria'::public.rarity, 'Ruta de los Príncipes', 'explore', 'Único principado de Bolivia otorgado por el Papa León XIII. Combina arquitectura gótica, bizantina, árabe y renacentista.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuB4zd-nmKZzG9xa98LJUg1z342tmUMwZEmJe1D4AcCYGOarmCo_hjRo6Q3AXhSXZOlZ6ZE3DA9Lin0QLluJ-93qZunZfVxOq5I7Z1lx_klw893OcBJJ6doTZkcUK_QBHbnfEjVwC_tIRgP1Ks1-IM8fhTflauOsvObSRKM-siyVlFQ40lYFLQIL9SmmOruLculrEHSxhXIfrwTXFwjPAJ58QH5L3jrtEl9W0rcM3ug'),
  ('catedral-metropolitana', 'catedral-metropolitana', 'Catedral Metropolitana', 'colonial', 'Panorámica', 'Rara'::public.rarity, 'Torre de la Catedral', 'church', 'Su torre campanario alberga relojes históricos y joyas religiosas invaluables como la Virgen de Guadalupe engarzada en perlas y rubíes.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDj0qwOSE1Va28E5Hrx2kNZA9hr3TP1NkdaWrxEg8MjiOehQYd2EzPL2xin5pZMUVUFnQQNeKLE0beZC1Dwe7Qbb6yAkSW1iAwY_IUXT0aXhO1Rdi_UGqSQYRqlO6OdfSzJXw2EDJf020n7E9Zl1J_6ogBp62osOXeAJRAvLay4dSvXteE_9X-SAQ44NJ6YEbOBHfgsk6AYoh6_zk3NzfJbntM-v9-6oEf0-fVqHus'),
  ('parque-cretacico', 'parque-cretacico', 'Parque Cretácico', 'mistica', 'Paleontología', 'Épica'::public.rarity, 'Acantilado Cal Orck''o', 'pets', 'El yacimiento de huellas de dinosaurio más grande del planeta. Un viaje geológico de 68 millones de años en el corazón de Chuquisaca.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCjpFCmwe14ldYgNVQEWbeqE4JhpZX2HGQf8EI8SWZWCyr3Tat0F1V8RCmzvrPnyh7f-ZoJKxEYK-HR91iPYW2AciHQspz6AtQsqgdzrU9WruH_UhKqRvPBfwTMy1fNJFYBiuxkC7PL_EHV-J7i1xzvt5iiFtum8bm_G-JCwnOlDrCDoSFhvYiLAIpY_8G_LV8DJHJxRF44x4bp_MZlPMgkxs7GYAFwCn4gEXACwKc')
insert into public.fun_facts (id, position, badge, icon, text_prefix, text_highlight, text_suffix, location, gradient) values
  ('dato-recoleta', 1, 'DATO DEL DÍA', 'park', '¿Sabías que el milenario cedro de ', 'La Recoleta', ' tiene siglos de historia y custodia el mirador más icónico de la ciudad blanca?', 'Mirador de La Recoleta', 'from-[#BA0C2F] via-[#8C0720] to-[#002855]'),
  ('dato-casa-libertad', 2, 'HISTORIA VIVA', 'history_edu', 'El ', 'Acta de la Independencia', ' te espera en la Casa de la Libertad intacta desde su firma el 6 de agosto de 1825.', 'Plaza 25 de Mayo', 'from-[#002855] via-[#103a6b] to-[#1E293B]'),
  ('dato-glorieta', 3, 'REALEZA BOLIVIANA', 'castle', 'En el fabuloso ', 'Castillo de La Glorieta', ' vivieron Don Francisco y Doña Clotilde, los únicos príncipes en la historia de Bolivia.', 'Carretera a Yotala', 'from-[#1E293B] via-[#4A0E17] to-[#BA0C2F]'),
  ('dato-cal-orcko', 4, 'MUNDO CRETÁCICO', 'pets', 'El farallón de ', 'Cal Orck''o', ' alberga el yacimiento con huellas de dinosaurio más grande del planeta con más de 12.000 pisadas.', 'Parque Cretácico', 'from-[#0F172A] via-[#002855] to-[#1E3A8A]')
